Code.NativeIaC:
```bicep
// Send audit logs from an Azure AI services account to Log Analytics
resource account 'Microsoft.CognitiveServices/accounts@2024-10-01' existing = {
  name: '<example_resource_name>'
}

resource diagnostics 'Microsoft.Insights/diagnosticSettings@2021-05-01-preview' = {
  name: '<example_resource_name>'
  scope: account
  properties: {
    workspaceId: '<log_analytics_workspace_id>'
    logs: [
      {
        categoryGroup: 'audit' // CRITICAL: sends audit logs
        enabled: true
      }
    ]
  }
}
```

Code.Terraform:
```hcl
resource "azurerm_monitor_diagnostic_setting" "<example_resource_name>" {
  name                       = "<example_resource_name>"
  target_resource_id         = azurerm_cognitive_account.<example_resource_name>.id
  log_analytics_workspace_id = azurerm_log_analytics_workspace.<example_resource_name>.id

  enabled_log {
    category_group = "audit" # CRITICAL: sends audit logs
  }
}
```
